@typeparam TItem

<ul class="sortable-list">
    @for (int i = 0; i < _internalItems.Count; i++)
    {
        var index = i;
        var item = _internalItems[index];
        <li class="sortable-list-item">
            <div class="sortable-list-item-content">
                @ItemTemplate(item)
            </div>
            <div class="sortable-list-item-actions">
                <button @onclick="() => MoveUp(index)" disabled="@(index == 0)">Move Up</button>
                <button @onclick="() => MoveDown(index)" disabled="@(index == _internalItems.Count - 1)">Move Down</button>
            </div>
        </li>
    }
</ul>

using Microsoft.AspNetCore.Components;

public partial class SortableList<TItem>
{
    private List<TItem> _internalItems = new();

    [Parameter, EditorRequired]
    public IReadOnlyList<TItem> Items { get; set; } = Array.Empty<TItem>();

    [Parameter, EditorRequired]
    public RenderFragment<TItem> ItemTemplate { get; set; } = default!;

    [Parameter]
    public EventCallback<List<TItem>> OnOrderChanged { get; set; }

    protected override void OnParametersSet()
    {
        _internalItems = Items.ToList();
    }

    private async Task MoveUp(int index)
    {
        if (index <= 0) return;

        (_internalItems[index - 1], _internalItems[index]) =
            (_internalItems[index], _internalItems[index - 1]);

        await OnOrderChanged.InvokeAsync(new List<TItem>(_internalItems));
    }

    private async Task MoveDown(int index)
    {
        if (index >= _internalItems.Count - 1) return;

        (_internalItems[index], _internalItems[index + 1]) =
            (_internalItems[index + 1], _internalItems[index]);

        await OnOrderChanged.InvokeAsync(new List<TItem>(_internalItems));
    }
}

